-- 0046_ncm_referencia.sql
-- Tabela de referencia curada de NCM para papelaria. NAO e usada em matching
-- automatico (so consulta manual/apoio) - decisao explicita do Joaquim.
create table if not exists ncm_referencia (
  id bigint generated by default as identity primary key,
  categoria_papelaria text not null unique,
  ncm text not null,
  descricao_oficial text not null,
  confianca text not null default 'confirmado'
    check (confianca in ('confirmado', 'inferido', 'nao_confirmado')),
  observacao text,
  fonte_url text,
  created_at timestamptz not null default now()
);

comment on table ncm_referencia is
  'Tabela de referencia (consulta manual) de NCM para produtos de papelaria. Nao alimenta nenhum matching automatico - cadastro feito deliberadamente a parte (decisao de 2026-11-09).';
comment on column ncm_referencia.categoria_papelaria is
  'Categoria interna de papelaria usada para localizar o NCM (ex.: cadernos, fita_adesiva). Chave unica.';
comment on column ncm_referencia.confianca is
  'confirmado = NCM validado em fonte oficial/especializada. inferido = deduzido por regras (gramatura, etc), sem fonte que cite o produto final. nao_confirmado = melhor candidato encontrado, precisa checar com contador antes de usar.';
comment on column ncm_referencia.observacao is
  'Ressalvas (ex.: depende de gramatura, composicao de fibra, material da superficie) que podem mudar o NCM do produto real.';

